"""Regenerates frontend/src/engine/texts.gen.ts from backend/app/i18n.py (run from the repo root)."""

import json
import sys
from pathlib import Path

root = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(root / "backend"))
from app.i18n import TEXTS  # noqa: E402

header = """/**
 * Texts generated by the agents in German and English.
 * GENERATED from backend/app/i18n.py by scripts/gen-texts.py – edit there, then regenerate.
 */
export type Lang = 'de' | 'en'

export const TEXTS: Record<Lang, Record<string, string>> = """
(root / "frontend/src/engine/texts.gen.ts").write_text(header + json.dumps(TEXTS, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
